 where c.id in ('04f55de9-0ed7-5819-b4a7-0ae321a99b66', '06850f31-dc68-5110-ac28-0f86e98b1791', '07f82551-a4d0-5b6e-b271-443e4999b945', '0879c3f8-8bae-5071-b58e-6ff0ebdba40e', '13ec081f-06a4-52a5-99df-6bfb4321c852', '1591e4d1-207d-50a3-bf72-4155db9ddbf0', '15d33bb9-bb1a-5f68-96db-e8ee347c0be2', '1b404be8-3c57-5c3f-b25c-99f67b8d2a57', '1c4ef7d8-30a8-59e3-b9bc-6f488d305f99', '1df68246-b02f-5e0d-8e5a-3bd1430055b0', '2c8cd7ee-e3d3-58d3-8ffe-420bf19fdb8e', '2e21e846-d671-5672-905c-395d9b734559', '2fb6ce2d-1734-5a31-994e-3b96d36c0522', '300b5143-b0eb-545b-8bb2-d35c66fd2004', '318010bf-019c-5e76-86ff-4cb83577f32c', '32fbae58-4fa2-52ed-ab9c-e3045f0b36fe', '36fee9fc-891e-56bd-b4ba-50104fc4aa31', '384be560-56c7-51e2-9893-766f94eb16b4', '3879ffa7-9607-53f0-a98a-36d77f8820be', '391a105e-0fee-5a1d-a055-904748c47409', '3deb423c-490e-5967-85c0-df41c37f3091', '3e091178-a6fb-514b-9c2f-c1b53290a288', '3eccfc73-4c54-584c-afd9-2813c7919110', '3fe77b45-5644-575f-9b9f-702263ea2c7b', '4493a550-9404-5c10-a88b-3d6e2ebe3ad4', '478c52ca-ccf4-5b83-8f0e-2d35adfccfb9', '493a6993-cda0-5fee-b73f-735a7978d6d9', '4be1d05d-bb39-5efc-a3fb-366c30c32bf7', '5a24e65b-d934-529b-be97-ac5da283b423', '5cbe41fd-394e-5799-94e1-9ffe2627dda3', '60c77805-3f33-5f7a-988a-dcd34fc532ca', '61382e6d-9f75-54f2-b62d-b32f8a46a426', '681580a7-f33b-5bd7-863c-f20f2f497e92', '6c4768c0-e6c4-5ac0-b4d3-953f655a0cb4', '6e48675f-0669-553d-ac4f-e794bd87f41d', '6e627a7d-1e99-57a3-b459-fbacb7caa739', '6ef718ff-5a58-5f11-9b4b-b5a6e74da42f', '6f4aa1e9-7b2e-5e30-9f1f-1bb1ca01a398', '7042acda-e967-50c9-82e9-ccdb1ec97fe8', '70479b5b-f4f2-5c02-8ba6-635e62b6b351', '718c8f34-e896-5b7f-9188-585ae107ad5d', '7b6dd53a-6ee3-5b74-a9b0-b3b0cbc5eac4', '7bef337d-7c05-5914-ac05-1dabb977a838', '7f258d5d-ed0e-5352-a471-6be87a3d2eb6', '83c1bbe5-d130-5039-bf75-94e1be89f88a', '870a0d7d-aec9-588e-bdcc-ce4ceacdb1df', '8a03a451-ed01-5889-8ab0-604b3713cfed', '8af96e36-7cf8-5c19-931e-dbfea4af1d55', '8f2df6ca-e24c-55d7-8b3f-201d52f3353f', '901816d9-4b24-5502-b329