   and not exists (select 1 from public.content_reviews r where r.entity_id = c.id and r.notes = 'a2_v2_dialogues: діалоги A2 доповнено до ≥ 6 реплік (2026-11-15, рішення власника: у діалозі не менше 6 реплік). Бета, потрібна перевірка носієм.');

-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_short int; v_long int; v_new int; v_gap int;
begin
  select count(*) into v_short from public.conversations c join public.lessons l on l.id = c.lesson_id
   where l.level_code = 'A2' and c.source = 'claude_curriculum_a2_v2'
     and (select count(*) from public.conversation_turns t where t.conversation_id = c.id) < 6;
  select count(*) into v_long from public.conversations c join public.lessons l on l.id = c.lesson_id
   where l.level_code = 'A2' and c.source = 'claude_curriculum_a2_v2'
     and (select count(*) from public.conversation_turns t where t.conversation_id = c.id) > 8;
  select count(*) into v_new from public.conversation_turns where id in (select (x->>'id')::uuid from jsonb_array_elements('[{"id": "1d5ac1fb-4c1d-509c-8e05-8f9ff48fef63", "conv": "2c8cd7ee-e3d3-58d3-8ffe-420bf19fdb8e", "speaker": "Darja", "hr": "Hvala lijepa, vrlo ste ljubazni.", "ua": "Щиро дякую, ви дуже люб’язні.", "ord": 6}, {"id": "ea36904e-ffc4-5a8a-97b4-bec091216704", "conv": "9140c599-ceba-5bbb-8214-54c16f55a70c", "speaker": "Konobar", "hr": "Naravno. Platit ćete gotovinom ili karticom?", "ua": "Звісно. Платитимете готівкою чи карткою?", "ord": 6}, {"id": "cbf1a1b1-8d89-5c72-9239-16b8efd39dc2", "conv": "4493a550-9404-5c10-a88b-3d6e2ebe3ad4", "speaker": "Daša", "hr": "Dobro, javi mi kad budemo blizu pristaništa.", "ua": "Добре, скажи мені, коли будемо біля пристані.", "ord": 6}, {"id": "1163b934-7797-590f-b0b0-1113d92c1128", "conv": "3eccfc73-4c54-584c-afd9-2813c7919110", "speaker": "Filip", "hr": "Može. Tata, ideš sa mnom do plutače?", "ua": "Гаразд. Тату, попливеш зі мною до буя?", "ord": 6}, {"id": "ef5f71bc-18cb-57b3-bac6-ec2740373f3b", "conv": "6e48675f-0669-553d-ac4f-e794bd87f41d", "speaker": "Darja", "hr": "Hoću. I kupit ću ulaznice odmah, dok još ima termina.", "ua": "Візьму. І куплю квитки зараз, поки ще є вільний час.", "ord": 6}, {"id": "5ae9c15c-c203-58a9-a54b-a16941e36856", "conv": "60c77805-3f33-5f7a-988a-dcd34fc532ca", "speaker": "Ivan", "hr": "Hvala lijepa i oprostite još jednom.", "ua": "Щиро дякую і ще раз перепрошую.", "ord": 6}, {"id": "27ccc66e-e64f-5401-b3ab-114dcad48a6f", "conv": "478c52ca-ccf4-5b83-8f0e-2d35adfccfb9", "speaker": "Darja", "hr": "Hoću, ali prvo moram još vježbati izgovor.", "ua": "Запишуся, але спершу маю ще повправлятися у вимові.", "ord": 6}, {"id": "07c2a9bf-1dd7-51de-ad34-602c201d788c", "conv": "dc69dcd8-ddd4-5c6c-b7c8-2d9b9d770f84", "speaker": "Daša", "hr": "Znam, iskaznicu ću dobiti u studentskoj službi.", "ua": "Знаю, студентський я отримаю у студентському відділі.", "ord": 6}, {"id": "0fdb6ae7-ab6a-52e0-bdf9-c0813e708e22", "conv": "d8bce6ec-0316-5fe5-a79c-7a3f296ddf01", "speaker": "Daša", "hr": "Rekla sam mu. Asistent ima konzultacije srijedom.", "ua": "Я йому сказала. Асистент проводить консультації по середах.", "ord": 6}, {"id": "8af4d202-dcd9-50ac-80ef-e20b020ae0e5", "conv": "a370c59a-771e-5703-a2f1-b65200d3955f", "speaker": "Marko", "hr": "Onda se prijavi na Zavod, možda dobiješ vaučer za obrazovanje.", "ua": "Тоді зареєструйся в службі зайнятості, може, отримаєш ваучер на навчання.", "ord": 6}, {"id": "32bbff6f-4155-5686-9440-56949bc08be0", "conv": "d50413e8-0f04-5bd4-8af4-565b6b3e6db0", "speaker": "Darja", "hr": "Hvala Vam, sad mi je puno jasnije.", "ua": "Дякую вам, тепер мені набагато зрозуміліше.", "ord": 6}, {"id": "8e917284-54ba-585d-b161-e53b7cb8a322", "conv": "06850f31-dc68-5110-ac28-0f86e98b1791", "speaker": "Učiteljica", "hr": "Zaslužio je. Vidimo se na roditeljskom sastanku.", "ua": "Він заслужив. Побачимося на батьківських зборах.", "ord": 6}, {"id": "ffdd37c5-64bb-5353-8400-004d891cdb25", "conv": "f17c113b-71a5-50a2-9b00-03d781e34eb2", "speaker": "Darja", "hr": "Dobro, sutra donosim i ispričnicu i suglasnost.", "ua": "Добре, завтра принесу і довідку, і згоду.", "ord": 6}, {"id": "5d90050e-1ce1-53f8-aa2a-164d6123965a", "conv": "b2f1d008-6695-5461-bba0-4495732d5145", "speaker": "Tajnica", "hr": "Onda samo ispunite upisnicu za boravak.", "ua": "Тоді просто заповніть бланк запису на продовжений день.", "ord": 6}, {"id": "223617dc-7bba-527e-bd28-a44f0b96e9ca", "conv": "32fbae58-4fa2-52ed-ab9c-e3045f0b36fe", "speaker": "Darja", "hr": "Super, pogledat ćemo ga sutra s Filipom.", "ua": "Супер, подивимося його завтра з Філіпом.", "ord": 6}, {"id": "305c1b34-e5ba-5de0-ab6c-416fcdf51a27", "conv": "1c4ef7d8-30a8-59e3-b9bc-6f488d305f99", "speaker": "Marko", "hr": "Glumica? Pa ti si i danas prava glumica!", "ua": "Актрисою? Та ти й сьогодні справжня актриса!", "ord": 6}, {"id": "fe48e19f-cd20-56a2-b75b-4f593d254ed8", "conv": "493a6993-cda0-5fee-b73f-735a7978d6d9", "speaker": "Ivan", "hr": "Vjerujem. Mi smo samo jednom markirali, ali nas nisu uhvatili.", "ua": "Вірю. Ми лише раз прогуляли, але нас не спіймали.", "ord": 6}, {"id": "62a1f3a8-bca6-5c61-a194-5cf2f568102f", "conv": "8f2df6ca-e24c-55d7-8b3f-201d52f3353f", "speaker": "Daša", "hr": "Šteta za kino. Sigurno je bilo lijepo.", "ua": "Шкода кінотеатру. Мабуть, там було гарно.", "ord": 6}, {"id": "2bb1b882-de9e-5723-ad02-062eb9fe407d", "conv": "7b6dd53a-6ee3-5b74-a9b0-b3b0cbc5eac4", "speaker": "Ivan", "hr": "Onda ga dobro čuvaj, to je obiteljsko blago.", "ua": "Тоді добре бережи його, це сімейний скарб.", "ord": 6}, {"id": "7b79f3ca-e646-5c7b-a537-56fb380e31fa", "conv": "718c8f34-e896-5b7f-9188-585ae107ad5d", "speaker": "Daša", "hr": "Da, prava prekretnica u našem životu.", "ua": "Так, справжній переломний момент у нашому житті.", "ord": 6}, {"id": "9958f03a-5fa8-51d3-8225-30fe92d1e1e0", "conv": "5a24e65b-d934-529b-be97-ac5da283b423", "speaker": "Ivan", "hr": "Nevjerojatno! Imao si sreće.", "ua": "Неймовірно! Тобі пощастило.", "ord": 6}, {"id": "3d74befc-f87c-5187-b2e2-85e98b664731", "conv": "a4e75699-8b3a-5d5e-8f5b-074528b9c01b", "speaker": "Darja", "hr": "Mislim da ćemo se s ovim lijepo slagati.", "ua": "Думаю, з цим ми добре ладнатимемо.", "ord": 6}, {"id": "b4f800fa-8e40-5479-85a6-c684e432f888", "conv": "97be6792-8206-58bf-9b69-a928bd12a9b4", "speaker": "Marko", "hr": "Hvala, to mi je drago čuti.", "ua": "Дякую, приємно це чути.", "ord": 6}, {"id": "b561cedf-672d-507b-9a65-7908d8cb41b8", "conv": "300b5143-b0eb-545b-8bb2-d35c66fd2004", "speaker": "Darja", "hr": "Dobro, onda ćemo pripremiti omotnicu i kupiti svečanu odjeću.", "ua": "Добре, тоді підготуємо конверт і купимо святковий одяг.", "ord": 6}, {"id": "2c7473b1-4b1e-5f0c-95a6-319bb5bea86a", "conv": "1591e4d1-207d-50a3-bf72-4155db9ddbf0", "speaker": "Ivan", "hr": "Hvala ti, i tebi isto!", "ua": "Дякую, і тобі також!", "ord": 6}, {"id": "e2f674fb-56be-5c23-a9d4-bad3231eebf6", "conv": "f92d0f91-7b93-5941-a011-49fdb4554d12", "speaker": "Darja", "hr": "Pozdravi baku od mene. Drži se!", "ua": "Передай бабусі вітання від мене. Тримайся!", "ord": 5}, {"id": "6de4635c-efc7-5e50-9bbe-4f35cef71447", "conv": "f92d0f91-7b93-5941-a011-49fdb4554d12", "speaker": "Marko", "hr": "Hvala, prenijet ću joj.", "ua": "Дякую, я їй передам.", "ord": 6}, {"id": "7de93373-5b90-57c7-b683-c297b18420ca", "conv": "6ef718ff-5a58-5f11-9b4b-b5a6e74da42f", "speaker": "Darja", "hr": "Imaš pravo. Nazvat ću je odmah.", "ua": "Ти маєш рацію. Зараз їй подзвоню.", "ord": 6}, {"id": "1cdc07e1-2e60-5070-b998-6a5dc274afc0", "conv": "04f55de9-0ed7-5819-b4a7-0ae321a99b66", "speaker": "Oksana", "hr": "Može. Važno mi je da smo opet dobro.", "ua": "Можна. Мені важливо, що в нас знову все добре.", "ord": 6}, {"id": "91687191-4f3d-51a7-ac10-9b54d1ab8385", "conv": "7bef337d-7c05-5914-ac05-1dabb977a838", "speaker": "Darja", "hr": "To je dobar prijedlog. Tako imamo prednosti i sela i grada.", "ua": "Це добра пропозиція. Так ми маємо переваги і села, і міста.", "ord": 6}, {"id": "fbdb0edb-312b-530b-b801-491d88d60e64", "conv": "a6eba3f3-9c23-5ded-b7e1-5f6bb3eb9d56", "speaker": "Šef", "hr": "Dogovoreno. Od sljedećeg tjedna radimo od kuće srijedom.", "ua": "Домовилися. З наступного тижня працюємо з дому по середах.", "ord": 6}, {"id": "04873618-2c5e-565a-907d-f2927e515582", "conv": "3e091178-a6fb-514b-9c2f-c1b53290a288", "speaker": "Voditeljica", "hr": "Odmah ću to provjeriti i vratiti Vam novac.", "ua": "Я одразу це перевірю й поверну вам гроші.", "ord": 6}, {"id": "928d688d-b9f0-5028-9c53-01139a9e4139", "conv": "318010bf-019c-5e76-86ff-4cb83577f32c", "speaker": "Susjed", "hr": "Nema na čemu. Laku noć!", "ua": "Нема за що. На добраніч!", "ord": 6}, {"id": "17b399f6-d988-5e49-b223-007387b470b2", "conv": "4be1d05d-bb39-5efc-a3fb-366c30c32bf7", "speaker": "Predstavnica", "hr": "Odlično. Idemo na sljedeću točku.", "ua": "Чудово. Переходимо до наступного пункту.", "ord": 6}, {"id": "b88638e5-652e-5074-88bd-14f8df668489", "conv": "c3418200-c6a3-5355-bb30-a8328afc0c5a", "speaker": "Marko", "hr": "U redu, prezentacija će biti gotova do petka.", "ua": "Гаразд, презентація буде готова до п’ятниці.", "ord": 6}, {"id": "2928b9ed-dc60-53ed-96e3-e2d3a4346139", "conv": "929b5f4b-6026-53a7-bb3c-bd90736f3acf", "speaker": "Ivan", "hr": "Hvala, Dašo. To je sve za danas.", "ua": "Дякую, Дашо. На сьогодні все.", "ord": 6}, {"id": "d24a095c-138f-5964-b589-a9a4a34c321a", "conv": "ea4a1f58-c1f0-55c7-8248-9c6dd4fe5286", "speaker": "Klijent", "hr": "Hvala. Mogu li dobiti i cjenik za sljedeću godinu?", "ua": "Дякую. Чи можу я отримати й прейскурант на наступний рік?", "ord": 5}, {"id": "dedd4add-6a8d-5313-a87e-ca39f46b2d8c", "conv": "ea4a1f58-c1f0-55c7-8248-9c6dd4fe5286", "speaker": "Darja", "hr": "Svakako. Poslat ću ga u istom e-mailu.", "ua": "Звісно. Надішлю його в тому самому листі.", "ord": 6}, {"id": "1518f239-0fa4-5eb7-8191-820be1515130", "conv": "8a03a451-ed01-5889-8ab0-604b3713cfed", "speaker": "Darja", "hr": "Hvala lijepa. Moj broj je u potpisu e-maila.", "ua": "Щиро дякую. Мій номер — у підписі листа.", "ord": 6}, {"id": "21dbae3d-e632-555b-8f7c-ea440ce2eb9a", "conv": "681580a7-f33b-5bd7-863c-f20f2f497e92", "speaker": "Daša", "hr": "Hvala Vama. Doviđenja!", "ua": "Дякую вам. До побачення!", "ord": 6}, {"id": "5a1ad2aa-989d-592e-bf5b-f8cc9f1f4834", "conv": "a6159e27-ad5d-515e-af8d-2ab1bc7ee06e", "speaker": "Šefica", "hr": "Odlično, tako je sve riješeno.", "ua": "Чудово, так усе вирішено.", "ord": 6}, {"id": "d8c341b3-be24-5547-88ef-9ee4afc24845", "conv": "b5b1477b-4b6a-54e0-84a7-be89bf1dd927", "speaker": "Šef", "hr": "Dobro, samo se odmori i brzo ozdravi.", "ua": "Добре, головне — відпочивай і швидко одужуй.", "ord": 6}, {"id": "5b40281b-486e-58d3-8f1d-de84bdb7fa0a", "conv": "3deb423c-490e-5967-85c0-df41c37f3091", "speaker": "Šef", "hr": "Nema na čemu, zaslužili ste.", "ua": "Нема за що, ви заслужили.", "ord": 6}, {"id": "e067f770-b52b-5caf-95d1-61b8ea84b4c9", "conv": "a4f83775-7879-50fb-815e-4ff8891ebd65", "speaker": "Ivan", "hr": "Čestitam! Sretno na novom poslu.", "ua": "Вітаю! Успіхів на новій роботі.", "ord": 6}, {"id": "37855153-e44b-5bf9-8c2c-75873150717e", "conv": "83c1bbe5-d130-5039-bf75-94e1be89f88a", "speaker": "Daša", "hr": "Mislim da jest, jamstveni list je u ladici.", "ua": "Думаю, що так, гарантійний талон у шухляді.", "ord": 6}, {"id": "a83589df-7e09-5b80-afc3-347d50699254", "conv": "9b75b305-9e89-51eb-bf45-af802baee4ac", "speaker": "Ivan", "hr": "Dobro, platit ću preko internetskog bankarstva.", "ua": "Добре, я заплачу через інтернет-банк.", "ord": 5}, {"id": "3f77f53b-3e02-5bb1-9e2c-1348449eb0f9", "conv": "9b75b305-9e89-51eb-bf45-af802baee4ac", "speaker": "Daša", "hr": "Samo pazi da točno upišeš poziv na broj.", "ua": "Лише стеж, щоб правильно вписати призначення платежу.", "ord": 6}, {"id": "530e7e0b-b1f7-5c97-8b99-fa398f22617a", "conv": "2fb6ce2d-1734-5a31-994e-3b96d36c0522", "speaker": "Službenica", "hr": "Obično do mjesec dana nakon procjene.", "ua": "Зазвичай до місяця після оцінки.", "ord": 6}, {"id": "a9bb3006-bcf6-5492-a1a9-9c0f4ca21df2", "conv": "a6c3344f-70d1-5470-893a-19bf6215b1a4", "speaker": "Sestra", "hr": "Recite to liječniku, pogledat će Vam i nogu.", "ua": "Скажіть це лікарю, він огляне й ногу.", "ord": 6}, {"id": "f93d8eac-36fd-5eff-9510-ad102a8e0734", "conv": "384be560-56c7-51e2-9893-766f94eb16b4", "speaker": "Liječnik", "hr": "Javite. I pijte puno tekućine, a ako počnete povraćati, dođite opet.", "ua": "Повідомте. І пийте багато рідини, а якщо почнете блювати, приходьте знову.", "ord": 6}, {"id": "3d984be5-e6ed-5009-b126-acfa96d38d9b", "conv": "dadc460c-d03f-5fe3-83d1-6841c31c55f4", "speaker": "Ivan", "hr": "Hoću. Od sutra kuham s manje soli.", "ua": "Добре. Із завтрашнього дня готуватиму з меншою кількістю солі.", "ord": 6}, {"id": "e645c8ef-e3ac-562c-aaf5-baca92975346", "conv": "3879ffa7-9607-53f0-a98a-36d77f8820be", "speaker": "Daša", "hr": "Tko joj pomaže s inzulinom?", "ua": "Хто їй допомагає з інсуліном?", "ord": 5}, {"id": "2e482858-fd1a-516f-b881-3bfbcac19a30", "conv": "3879ffa7-9607-53f0-a98a-36d77f8820be", "speaker": "Darja", "hr": "Nitko, sve radi sama. Jednom mjesečno ide na kontrolni pregled.", "ua": "Ніхто, усе робить сама. Раз на місяць ходить на контрольний огляд.", "ord": 6}, {"id": "9edae2a5-0931-59f6-adaf-f1942f3cfbaf", "conv": "d27e73c4-b6ff-58c2-9fd7-fcfb10544a37", "speaker": "Darja", "hr": "Znam. Ovaj vikend ću isključiti mobitel i otići u prirodu.", "ua": "Знаю. Цих вихідних вимкну мобільний і поїду на природу.", "ord": 6}, {"id": "3416fb02-6989-5890-8bf9-0bb8d10d267a", "conv": "fae2eba7-76f3-5103-bdf5-955258af3416", "speaker": "Ivan", "hr": "Nisam znao da su razgovori besplatni.", "ua": "Я не знав, що розмови безкоштовні.", "ord": 5}, {"id": "e231dd7a-827e-51a2-95b2-d699ed2fea1a", "conv": "fae2eba7-76f3-5103-bdf5-955258af3416", "speaker": "Marko", "hr": "Jesu. Ja sam išao prošle godine i puno mi je pomoglo.", "ua": "Так. Я ходив торік, і мені це дуже допомогло.", "ord": 6}, {"id": "7be10b33-6e3e-5c70-a3d3-fd5a4b51c68a", "conv": "9d135708-89e8-5dac-90b8-09c185bc9bfb", "speaker": "Darja", "hr": "Dobra ideja. Uzet ću i fotografiju za dokumente.", "ua": "Добра ідея. Візьму й фото на документи.", "ord": 6}, {"id": "f5fbce83-af95-58e4-ab6c-dfdf76a7bceb", "conv": "13ec081f-06a4-52a5-99df-6bfb4321c852", "speaker": "Ivan", "hr": "Hvala, vidimo se za dva tjedna.", "ua": "Дякую, побачимося за два тижні.", "ord": 6}, {"id": "5ae7845b-9f1f-531f-b730-db25634e8290", "conv": "bb0af795-2fb6-5d37-9760-a0745296e920", "speaker": "Vozač", "hr": "U redu. Ja ću nazvati osiguranje i pitati trebamo li zvati policiju.", "ua": "Гаразд. Я подзвоню у страхову й спитаю, чи треба викликати поліцію.", "ord": 6}, {"id": "21204b98-c5ec-5f2c-aeeb-5a015841de7e", "conv": "9d3f077b-d4ca-58e1-9407-20efb4480b94", "speaker": "Ivan", "hr": "Onda ću platiti odmah. Ubuduće ću voziti pažljivije.", "ua": "Тоді заплачу одразу. Надалі їздитиму уважніше.", "ord": 6}, {"id": "c2d9346f-e483-57a1-a2b1-1c519f37b6f2", "conv": "946b5567-f486-5d56-b97a-5f1aad43a7b9", "speaker": "Ivan", "hr": "Nazvat ću prometno redarstvo i pitati.", "ua": "Подзвоню в дорожню службу міста й спитаю.", "ord": 6}, {"id": "4d858365-4451-59c9-95e1-b0dae250dfc2", "conv": "7042acda-e967-50c9-82e9-ccdb1ec97fe8", "speaker": "Ivan", "hr": "Dobro, a ja ću napuniti spremnik večeras.", "ua": "Добре, а я заправлю бак сьогодні ввечері.", "ord": 6}, {"id": "34e66355-deb6-5b9b-83cf-ef9d7665fdaa", "conv": "07f82551-a4d0-5b6e-b271-443e4999b945", "speaker": "Daša", "hr": "Dobro, ali vozi oprezno, cesta je uska.", "ua": "Добре, але їдь обережно, дорога вузька.", "ord": 6}, {"id": "a97f47ed-d836-5db5-b49a-4fec0780a7ba", "conv": "2e21e846-d671-5672-905c-395d9b734559", "speaker": "Prodavač", "hr": "Može. Ponesite osobnu iskaznicu i prometnu dozvolu.", "ua": "Гаразд. Візьміть посвідчення особи й техпаспорт.", "ord": 6}, {"id": "518fad8f-e3ef-52b4-a8e1-e2ed3da0c5ac", "conv": "bb42ca2a-7080-58a0-b36b-e6b6e4f99955", "speaker": "Ivan", "hr": "Dobro, ali sutra ću ipak otići u ured za izgubljene stvari.", "ua": "Добре, але завтра таки піду в бюро знахідок.", "ord": 6}, {"id": "b92a360f-ab33-5612-9f39-e3a85956e600", "conv": "d54af43b-a034-5ea0-8cfc-c16695c1c8f3", "speaker": "Daša", "hr": "Vrijedi. Raspored odvoza sam stavila na hladnjak.", "ua": "Варте. Графік вивезення я повісила на холодильник.", "ord": 6}, {"id": "05c95c71-edc2-59b6-bf74-e0967ed4ee44", "conv": "0879c3f8-8bae-5071-b58e-6ff0ebdba40e", "speaker": "Ivan", "hr": "Imaš pravo. Nazvat ću ih sutra ujutro.", "ua": "Ти маєш рацію. Подзвоню їм завтра зранку.", "ord": 5}, {"id": "79bd5eb9-7b71-525e-bd1c-d421b41f3371", "conv": "0879c3f8-8bae-5071-b58e-6ff0ebdba40e", "speaker": "Daša", "hr": "I zapiši broj prijave da možeš provjeriti.", "ua": "І запиши номер заявки, щоб можна було перевірити.", "ord": 6}, {"id": "a34ec1ab-d754-53fa-b8ca-f7b3cc9a9237", "conv": "15d33bb9-bb1a-5f68-96db-e8ee347c0be2", "speaker": "Darja", "hr": "Tako je. Vidimo se u subotu na plaži!", "ua": "Саме так. Побачимося в суботу на пляжі!", "ord": 6}, {"id": "7c4e76e8-9000-5849-89e0-dcf99c7af405", "conv": "951e274c-c212-5417-a726-2c5ade6acaa4", "speaker": "Ivan", "hr": "Možete se prijaviti i na ekološku akciju u kvartu.", "ua": "Можете ще записатися на екологічну акцію в районі.", "ord": 5}, {"id": "923f0e5e-dae7-5972-8b39-b8c9bce3106a", "conv": "951e274c-c212-5417-a726-2c5ade6acaa4", "speaker": "Marko", "hr": "Dobra ideja, povest ću i djecu.", "ua": "Добра ідея, візьму з собою й дітей.", "ord": 6}, {"id": "a3f416b5-e5af-52e8-9dbd-90918f261eb4", "conv": "b0c9465c-98fe-557b-9158-64006bbc4d81", "speaker": "Ivan", "hr": "Dobro. Napunit ću i boce pitkom vodom.", "ua": "Добре. Наповню й пляшки питною водою.", "ord": 5}, {"id": "026fdcd0-3a85-5da2-a948-a80c42509142", "conv": "b0c9465c-98fe-557b-9158-64006bbc4d81", "speaker": "Marko", "hr": "I prati upute hitnih službi na radiju.", "ua": "І стеж за вказівками екстрених служб по радіо.", "ord": 6}, {"id": "a62afcd5-cb89-53a0-b650-0fb952c84c8a", "conv": "c40ff1f9-49f9-5531-aa24-6bad1a4f95a3", "speaker": "Ivan", "hr": "A koliko često ih trebam zalijevati?", "ua": "А як часто їх треба поливати?", "ord": 5}, {"id": "03b7c1cb-0abb-5f82-aee7-0a160dc76ed7", "conv": "c40ff1f9-49f9-5531-aa24-6bad1a4f95a3", "speaker": "Prodavačica", "hr": "Ljeti jednom tjedno, a zimi gotovo nikad.", "ua": "Улітку раз на тиждень, а взимку майже ніколи.", "ord": 6}, {"id": "1c0537da-6587-5582-a05c-f6ac000e76e4", "conv": "db8f6605-1bab-5f3a-a4fe-2fcaea004bde", "speaker": "Darja", "hr": "Dobro, pa mi sutra javi je li istina.", "ua": "Добре, тоді завтра скажи мені, чи це правда.", "ord": 6}, {"id": "eb7a4af2-eb27-5027-a4c5-9c41aef5206c", "conv": "b20264d2-384c-52c9-a0fd-e30b9b99cb4c", "speaker": "Marko", "hr": "Može, poslat ću ti ga odmah.", "ua": "Гаразд, зараз тобі надішлю.", "ord": 6}, {"id": "9ed434ec-351e-53d5-89d1-321dd73cf2bb", "conv": "e9cd1078-9c46-51a9-baff-67d16fdd53bd", "speaker": "Daša", "hr": "I dodaj fotografiju, tako se brže prodaje.", "ua": "І додай фотографію, так швидше продається.", "ord": 6}, {"id": "07ba269f-4114-50e8-94da-8d1d81751199", "conv": "fb0e71a3-40ab-520f-8332-006b7095a15e", "speaker": "Ivan", "hr": "Znam, ali naša stara perilica stalno curi.", "ua": "Знаю, але наша стара пральна машина постійно протікає.", "ord": 5}, {"id": "641327d9-b7ca-578f-9d3b-daf0d530b4d1", "conv": "fb0e71a3-40ab-520f-8332-006b7095a15e", "speaker": "Marko", "hr": "Onda je kupi, ali prvo usporedi cijene na internetu.", "ua": "Тоді купуй, але спершу порівняй ціни в інтернеті.", "ord": 6}, {"id": "c12e1591-4dd5-5388-9924-511bbfc88b80", "conv": "6e627a7d-1e99-57a3-b459-fbacb7caa739", "speaker": "Ivan", "hr": "Odlično, posudit ću jednu zvučnu knjigu za put.", "ua": "Чудово, візьму одну аудіокнигу в дорогу.", "ord": 5}, {"id": "91729f24-9c54-56e6-a586-4101a39409ff", "conv": "6e627a7d-1e99-57a3-b459-fbacb7caa739", "speaker": "Knjižničarka", "hr": "Izvolite, zvučne knjige su na ovoj polici.", "ua": "Прошу, аудіокниги — на цій полиці.", "ord": 6}, {"id": "24972d46-8190-571f-b422-b7ad041fa945", "conv": "7f258d5d-ed0e-5352-a471-6be87a3d2eb6", "speaker": "Marko", "hr": "Samo mi nemoj otkriti kraj! Idemo u petak.", "ua": "Тільки не розповідай мені фінал! Ідемо в п’ятницю.", "ord": 6}, {"id": "4087ae65-2e3c-5084-bc14-0be964c6cf4a", "conv": "391a105e-0fee-5a1d-a055-904748c47409", "speaker": "Ivan", "hr": "Super, vrijedi probati. Što preporučuješ?", "ua": "Супер, варто спробувати. Що порадиш?", "ord": 5}, {"id": "49e299ec-1cef-537b-b750-22af5bfa9a1d", "conv": "391a105e-0fee-5a1d-a055-904748c47409", "speaker": "Marko", "hr": "Riblju juhu i domaće vino. Toplo preporučujem!", "ua": "Рибну юшку й домашнє вино. Щиро раджу!", "ord": 6}, {"id": "1ef779c5-dc68-5286-9979-ef347e8915d1", "conv": "b4dd1542-9a39-5b6b-b285-9b12c3a68061", "speaker": "Daša", "hr": "Osim toga, kod kuće je teško odvojiti posao od odmora.", "ua": "До того ж удома важко відділити роботу від відпочинку.", "ord": 5}, {"id": "7bdbb9e0-2292-5f9f-9ff8-ec8e31f8acf0", "conv": "b4dd1542-9a39-5b6b-b285-9b12c3a68061", "speaker": "Marko", "hr": "To ima smisla. Zato je kompromis najbolji.", "ua": "Це має сенс. Тому компроміс — найкраще.", "ord": 6}, {"id": "8b5956df-bdf9-5010-9c67-5df8a5c6df77", "conv": "901816d9-4b24-5502-b329-f82ed5df6c32", "speaker": "Darja", "hr": "Super, hvala! Zapisat ću sve.", "ua": "Супер, дякую! Запишу все.", "ord": 6}, {"id": "ebda1ce7-ed59-547f-8dbd-692584f42b99", "conv": "ea41902f-49ed-54ff-9f1e-f1784e1cdb91", "speaker": "Ivan", "hr": "Zanimljivo, nisam to znao. Onda ćemo probati teran.", "ua": "Цікаво, я цього не знав. Тоді скуштуємо теран.", "ord": 6}, {"id": "232c0ad8-6130-54a1-8f9a-d2ed237c9740", "conv": "8af96e36-7cf8-5c19-931e-dbfea4af1d55", "speaker": "Ivana", "hr": "Onda moraš probati i šljivovicu, ali samo malo!", "ua": "Тоді мусиш скуштувати й сливовицю, але лише трохи!", "ord": 6}, {"id": "2494cdfa-bfbd-5061-8e9c-bf12bc8a4dc6", "conv": "a0280e79-456d-5bb6-93aa-c12f292d0773", "speaker": "Ivan", "hr": "Hvala, sigurno ćemo doći!", "ua": "Дякую, обов’язково приїдемо!", "ord": 6}, {"id": "d03b3fa3-580b-55f7-8cee-98d825e948a2", "conv": "fc8d293f-ae7b-51f3-8d3b-00631ee3094f", "speaker": "Darja", "hr": "Onda sigurno idem. Ponijet ću toplu jaknu.", "ua": "Тоді точно йду. Візьму теплу куртку.", "ord": 6}, {"id": "a16ece6e-003d-5fcc-9696-c29e835092aa", "conv": "3fe77b45-5644-575f-9b9f-702263ea2c7b", "speaker": "Darja", "hr": "Zvuči lijepo. Doći ću s Ivanom.", "ua": "Звучить гарно. Прийду з Іваном.", "ord": 6}, {"id": "8f86ecc4-454b-5721-b6d5-ca35e72f9e7c", "conv": "e750f0ad-479b-5b46-bd02-ce26a4d02da2", "speaker": "Darja", "hr": "Slažem se. Djeca trebaju znati svoje korijene.", "ua": "Згодна. Діти мають знати своє коріння.", "ord": 6}, {"id": "02f599e6-9297-5941-928f-b2121b30a9b2", "conv": "d853d368-6258-563b-90f4-35dde0a4b08c", "speaker": "Ivan", "hr": "Pazi i na rok važenja iskaznice stranca.", "ua": "Стеж і за строком дії посвідки іноземця.", "ord": 5}, {"id": "29ff5a76-349a-5f59-9b52-5e39425776e0", "conv": "d853d368-6258-563b-90f4-35dde0a4b08c", "speaker": "Darja", "hr": "Hvala, zapisat ću oba datuma u kalendar.", "ua": "Дякую, запишу обидві дати в календар.", "ord": 6}, {"id": "207f000e-dec5-572d-8760-df2388eb4d1d", "conv": "e47f499c-ffdb-5965-af60-4485408432bb", "speaker": "Ivan", "hr": "Super, dovest ću i suprugu. Trebamo li nešto ponijeti?", "ua": "Супер, приведу й дружину. Нам щось принести?", "ord": 5}, {"id": "ca478c36-45d4-5116-9d46-0e11d4c53a3b", "conv": "e47f499c-ffdb-5965-af60-4485408432bb", "speaker": "Darja", "hr": "Samo dobro raspoloženje. Poslije koncerta je druženje uz domaću hranu.", "ua": "Лише гарний настрій. Після концерту — зустріч за домашньою їжею.", "ord": 6}, {"id": "5ec0f90c-8564-5c10-9f28-42596090166b", "conv": "5cbe41fd-394e-5799-94e1-9ffe2627dda3", "speaker": "Ivan", "hr": "Dobro, doći ću u pola devet.", "ua": "Добре, прийду о пів на дев’яту.", "ord": 6}, {"id": "fd87118c-d9d0-5660-b007-d60f9aea7e70", "conv": "e1464610-4de1-54b2-bc69-512bc44e558d", "speaker": "Darja", "hr": "Hvala Vama. Svatko može pomoći, makar sat tjedno.", "ua": "Дякую вам. Кожен може допомогти, хоча б годину на тиждень.", "ord": 6}, {"id": "1a04f1c2-8d6f-5480-a00f-cc95db07f458", "conv": "ebb9c4b4-84f1-5b71-8fd4-9624d0a68027", "speaker": "Ivan", "hr": "Je li to sigurno?", "ua": "Це безпечно?", "ord": 5}, {"id": "8fed09ab-b912-5141-9a9a-d1dfa5d674c2", "conv": "ebb9c4b4-84f1-5b71-8fd4-9624d0a68027", "speaker": "Darja", "hr": "Jest, aplikacija je od moje banke. Uvijek dobijem potvrdu.", "ua": "Так, це застосунок мого банку. Я завжди отримую підтвердження.", "ord": 6}, {"id": "9346c8ae-7523-58d6-99c2-922f4c22c3f2", "conv": "61382e6d-9f75-54f2-b62d-b32f8a46a426", "speaker": "Marko", "hr": "Razumijem. Govori li kod kuće ukrajinski?", "ua": "Розумію. Удома він говорить українською?", "ord": 5}, {"id": "4c732186-8e9d-5eac-9f99-781c3b6c8532", "conv": "61382e6d-9f75-54f2-b62d-b32f8a46a426", "speaker": "Darja", "hr": "Govori, to nam je obiteljsko pravilo.", "ua": "Так, це наше сімейне правило.", "ord": 6}, {"id": "9dceee5c-e508-53ba-be9f-208dcc9bedc3", "conv": "e7cb2f53-f4a0-52a4-8e93-9bab35d715a4", "speaker": "Ivan", "hr": "Sretno! Ja štedim za vozački za motor.", "ua": "Успіхів! А я відкладаю на права на мотоцикл.", "ord": 5}, {"id": "872181c7-cd42-59dc-8801-173baa88a43f", "conv": "e7cb2f53-f4a0-52a4-8e93-9bab35d715a4", "speaker": "Marko", "hr": "Super cilj. Samo nemoj odustati!", "ua": "Чудова мета. Тільки не здавайся!", "ord": 6}, {"id": "4e23dd74-a2af-5bd4-bd5e-8715a41f00ea", "conv": "70479b5b-f4f2-5c02-8ba6-635e62b6b351", "speaker": "Marko", "hr": "Dobro, nagovorila si me. Počinjem od ponedjeljka!", "ua": "Добре, ти мене вмовила. Починаю з понеділка!", "ord": 6}, {"id": "f3f38ddc-2d10-5299-9a88-be6fcf90c571", "conv": "98708d7a-575a-54cc-b052-79fa25890dd4", "speaker": "Darja", "hr": "Vidimo se. Sretno na poslu!", "ua": "Побачимося. Успіхів на роботі!", "ord": 6}, {"id": "bacbb2a1-b5a9-5659-b4de-bae1a59aac2f", "conv": "6c4768c0-e6c4-5ac0-b4d3-953f655a0cb4", "speaker": "Sestra", "hr": "U redu. Brzo ozdravite!", "ua": "Гаразд. Швидкого одужання!", "ord": 6}, {"id": "255c53fe-fdc3-5e46-be16-47fe8c0123f0", "conv": "6f4aa1e9-7b2e-5e30-9f1f-1bb1ca01a398", "speaker": "Šef", "hr": "Dobro. Hvala što si pitala na vrijeme.", "ua": "Добре. Дякую, що спитала заздалегідь.", "ord": 6}, {"id": "974118a9-689d-5321-82f5-95572afc25e9", "conv": "870a0d7d-aec9-588e-bdcc-ce4ceacdb1df", "speaker": "Ivan", "hr": "Naravno. Gdje je blagajna?", "ua": "Звісно. Де каса?", "ord": 5}, {"id": "fb6b14d7-7daa-5d2d-9eb7-a20892f0b084", "conv": "870a0d7d-aec9-588e-bdcc-ce4ceacdb1df", "speaker": "Spasilac", "hr": "Na ulazu, desno od svlačionica.", "ua": "Біля входу, праворуч від роздягалень.", "ord": 6}, {"id": "80906d06-bc1c-508a-9e67-10463234728a", "conv": "1b404be8-3c57-5c3f-b25c-99f67b8d2a57", "speaker": "Daša", "hr": "Dogovoreno. Ako se išta promijeni, javi mi do petka.", "ua": "Домовилися. Якщо щось зміниться, повідом мені до п’ятниці.", "ord": 5}, {"id": "33a9021c-21cf-56e1-817d-d799dd64c7c1", "conv": "1b404be8-3c57-5c3f-b25c-99f67b8d2a57", "speaker": "Ivan", "hr": "Hoću. Dogovor je dogovor!", "ua": "Добре. Домовленість є домовленість!", "ord": 6}, {"id": "59011071-fa69-5816-9d9a-8cd9de719d1a", "conv": "1df68246-b02f-5e0d-8e5a-3bd1430055b0", "speaker": "Marko", "hr": "Može. Napravit ćemo anketu u grupnom chatu.", "ua": "Можна. Зробимо опитування в груповому чаті.", "ord": 5}, {"id": "0efa93ad-3a14-550b-b658-9bbd863a92b9", "conv": "1df68246-b02f-5e0d-8e5a-3bd1430055b0", "speaker": "Darja", "hr": "Super, neka većina odluči.", "ua": "Супер, хай більшість вирішить.", "ord": 6}, {"id": "fa5fce58-4627-57fc-825a-a98f5307ee12", "conv": "d498861a-4927-5dbb-bf81-e2adf7bb9ea9", "speaker": "Darja", "hr": "Istina. Sad se puno bolje snalazim.", "ua": "Правда. Тепер я набагато краще даю собі раду.", "ord": 6}, {"id": "352f6d00-3b34-5335-b175-561ed8d6db72", "conv": "36fee9fc-891e-56bd-b4ba-50104fc4aa31", "speaker": "Daša", "hr": "Savršeno! Olena će se jako obradovati.", "ua": "Чудово! Олена дуже зрадіє.", "ord": 6}]'::jsonb) x);
